/* NextNode core logic for the static demo pages — a direct port of the Python engine:
 *   app/graph/ontology.py  → canonicalKey, resolve, resolveDomain
 *   app/graph/scoring.py   → scoreGap, scorePivot
 *   app/graph/payloads.py  → buildGraphPayload, buildRoadmapFlow
 * Data comes from assets/data.js (generated by scripts/build_pages.py).
 * The demo page's self-test checks this port against results computed by the Python code. */
(function () {
  "use strict";
  const D = window.NEXTNODE;
  const NN = {};

  /* ── ontology ── */
  const SKILLS = Object.fromEntries(D.ontology.skills.map(s => [s.key, s]));
  const BY_NAME = Object.fromEntries(D.ontology.skills.map(s => [s.name, s]));
  const NEXT = {}, PREV = {}, STRENGTH = {};
  for (const [a, b, w] of D.ontology.prerequisites) {
    (NEXT[a] ||= []).push(b); (PREV[b] ||= []).push(a); STRENGTH[`${a}>${b}`] = w;
  }
  Object.assign(NN, { SKILLS, BY_NAME, NEXT, PREV, STRENGTH });

  NN.canonicalKey = text => {
    let s = String(text).normalize("NFKC").toLowerCase().replace(/[-_/]/g, " ").replace(/[^a-z0-9 +#.]/g, "");
    return s.replace(/\s+/g, " ").trim().replace(/\.+$/, "").trim();
  };
  NN.resolve = name => {
    if (!name) return null;
    const key = NN.canonicalKey(name);
    if (SKILLS[key]) return { skill: SKILLS[key], via: "name" };
    const target = D.ontology.aliases[key];
    return target ? { skill: SKILLS[target], via: "alias" } : null;
  };
  NN.resolveDomain = name => {
    if (!name) return null;
    const key = NN.canonicalKey(name).replace(/ /g, "_");
    return D.ontology.domains.includes(key) ? key : null;
  };
  NN.reach = src => { // skills reachable within 1..3 PREREQUISITE_OF hops
    const out = new Set(); let frontier = [src];
    for (let i = 0; i < 3; i++) {
      frontier = frontier.flatMap(s => NEXT[s] || []);
      frontier.forEach(t => out.add(t));
    }
    return out;
  };
  NN.shortestPath = (src, dst) => {
    let paths = [[src]];
    for (let i = 0; i < 3; i++) {
      const next = [];
      for (const p of paths) for (const t of NEXT[p[p.length - 1]] || []) {
        const np = [...p, t];
        if (t === dst) return np;
        next.push(np);
      }
      paths = next;
    }
    return null;
  };

  /* ── scoring (app/graph/scoring.py) ── */
  const round3 = x => Math.round(x * 1000) / 1000;
  const pct = x => `${Math.round(x * 100)}%`;
  const W = { core: 1.0, preferred: 0.6, nice_to_have: 0.2 };
  const TIER = { core: 0, preferred: 1, nice_to_have: 2 };
  NN.pct = pct; NN.round3 = round3; NN.TIER = TIER;

  function reasonFor(g) {
    if (g.status === "missing" && g.prereqs_owned > 0) return `Not in your profile but you own ${g.prereqs_owned} prerequisite(s) — quick to learn`;
    if (g.status === "missing" && g.importance === "core") return "Core requirement — not in your profile, address first";
    if (g.status === "missing" && g.importance === "nice_to_have") return "Nice to have — low urgency";
    if (g.status === "partial") return `You have this at ${pct(g.your_proficiency)} but ${pct(g.required_weight)} is expected`;
    return "Gap identified";
  }

  NN.scoreGap = (rows, sharedDomains, prereq) => {
    let gap = 0, max = 0;
    const breakdown = rows.map(r => {
      const mult = W[r.importance] ?? 0.2;
      const raw = r.status === "missing" ? r.required_weight : r.status === "partial" ? 0.5 * r.required_weight : 0;
      const owned = prereq[r.skill] || 0;
      const wg = raw * (1 - Math.min(owned * 0.15, 0.4)) * mult;
      gap += wg; max += r.required_weight * mult;
      return { skill: r.skill, category: r.category ?? null, importance: r.importance, status: r.status,
               your_proficiency: r.your_proficiency, required_weight: r.required_weight,
               prereqs_owned: owned, gap_contribution: round3(wg) };
    });
    const bonus = Math.min(sharedDomains * 0.025, 0.05);
    const fit = Math.min((max > 0 ? 1 - gap / max : 1) + bonus, 1);
    const roadmap = breakdown.filter(d => d.status !== "met")
      .sort((a, b) => (TIER[a.importance] - TIER[b.importance]) || (b.gap_contribution - a.gap_contribution))
      .map((g, i) => ({
        rank: i + 1, skill: g.skill,
        priority: g.importance === "core" ? (g.prereqs_owned === 0 ? "high" : "medium") : g.importance === "preferred" ? "medium" : "low",
        status: g.status, importance: g.importance, prereqs_owned: g.prereqs_owned, reason: reasonFor(g),
      }));
    return { fit_score: round3(fit), gap_score: round3(gap), domain_bonus: bonus, skill_breakdown: breakdown, roadmap };
  };

  /** owned: {canonicalName: proficiency}; requirements: [{skill, importance, weight}] (canonical, deduped). */
  NN.analyzeProfile = (owned, requirements, targetDomain, jobDomains) => {
    const rows = requirements.map(q => {
      const p = owned[q.skill];
      return { skill: q.skill, category: BY_NAME[q.skill]?.category ?? null, importance: q.importance,
               required_weight: q.weight, your_proficiency: p ?? 0,
               status: p === undefined ? "missing" : p >= q.weight ? "met" : "partial" };
    });
    const prereq = {}, unlocks = {};
    for (const r of rows.filter(r => r.status === "missing")) {
      unlocks[r.skill] = Object.keys(owned).filter(o => NN.reach(o).has(r.skill));
      prereq[r.skill] = unlocks[r.skill].length;
    }
    const shared = targetDomain && jobDomains.includes(targetDomain) ? 1 : 0;
    return { owned, rows, unlocks, shared, result: NN.scoreGap(rows, shared, prereq) };
  };

  /* ── frontend payloads (app/graph/payloads.py) ── */
  NN.prereqPaths = a => {
    const paths = [];
    for (const [target, owners] of Object.entries(a.unlocks)) for (const o of owners) {
      const p = NN.shortestPath(o, target);
      if (p) paths.push({ owned: o, proficiency: a.owned[o], target,
        edges: p.slice(1).map((t, i) => ({ source: p[i], target: t, strength: STRENGTH[`${p[i]}>${t}`] ?? null })) });
    }
    return paths;
  };

  NN.buildGraphPayload = (a, user, job, userDomains, jobDomains) => {
    const SIZE = { core: 4, preferred: 3, nice_to_have: 2 };
    const nodes = new Map(), links = new Map();
    const addLink = l => { const k = `${l.source}|${l.target}|${l.type}`; if (!links.has(k)) links.set(k, l); };
    const uid = `user:${user.id}`, jid = `job:${job.id}`;
    nodes.set(uid, { id: uid, label: user.name || user.id, type: "user", val: 8 });
    nodes.set(jid, { id: jid, label: job.title || job.id, type: "job", val: 8 });
    for (const s of a.result.skill_breakdown) {
      const sid = `skill:${s.skill}`, has = s.status !== "missing";
      nodes.set(sid, { id: sid, label: s.skill, type: "skill", status: s.status, importance: s.importance,
        proficiency: has ? s.your_proficiency : null, required_weight: s.required_weight, val: SIZE[s.importance] || 2 });
      addLink({ source: jid, target: sid, type: "REQUIRES_SKILL", importance: s.importance, weight: s.required_weight });
      if (has) addLink({ source: uid, target: sid, type: "HAS_SKILL", proficiency: s.your_proficiency });
    }
    const paths = NN.prereqPaths(a);
    for (const p of paths) for (const e of p.edges) {
      for (const name of [e.source, e.target]) if (!nodes.has(`skill:${name}`)) {
        const own = name in a.owned;
        nodes.set(`skill:${name}`, { id: `skill:${name}`, label: name, type: "skill", status: own ? "owned" : "prerequisite",
          proficiency: own ? a.owned[name] : null, val: 1.5 });
      }
      addLink({ source: `skill:${e.source}`, target: `skill:${e.target}`, type: "PREREQUISITE_OF", strength: e.strength });
    }
    for (const p of paths) addLink({ source: uid, target: `skill:${p.owned}`, type: "HAS_SKILL", proficiency: p.proficiency });
    for (const d of userDomains) { nodes.set(`domain:${d}`, { id: `domain:${d}`, label: d, type: "domain", val: 3 }); addLink({ source: uid, target: `domain:${d}`, type: "TARGETS" }); }
    for (const d of jobDomains) { nodes.set(`domain:${d}`, { id: `domain:${d}`, label: d, type: "domain", val: 3 }); addLink({ source: jid, target: `domain:${d}`, type: "IN_DOMAIN" }); }
    return { nodes: [...nodes.values()], links: [...links.values()] };
  };

  NN.buildRoadmapFlow = a => {
    const roadmap = a.result.roadmap, y = {}, nodes = [], edges = [];
    for (const s of roadmap) {
      y[s.skill] = (s.rank - 1) * 140;
      nodes.push({ id: `step:${s.skill}`, type: "roadmapStep", position: { x: 0, y: y[s.skill] },
        data: { label: s.skill, rank: s.rank, priority: s.priority, status: s.status, importance: s.importance,
                reason: s.reason, prereqs_owned: s.prereqs_owned } });
    }
    roadmap.slice(1).forEach((b, i) => edges.push({ id: `seq:${roadmap[i].rank}-${b.rank}`, source: `step:${roadmap[i].skill}`,
      target: `step:${b.skill}`, type: "smoothstep", label: null, animated: false, data: { kind: "sequence" } }));
    const unlocks = {};
    for (const [t, owners] of Object.entries(a.unlocks)) if (t in y) for (const o of owners) (unlocks[o] ||= []).push(t);
    let last = null;
    for (const o of Object.keys(unlocks).sort((p, q) => Math.min(...unlocks[p].map(t => y[t])) - Math.min(...unlocks[q].map(t => y[t])) || p.localeCompare(q))) {
      let oy = Math.min(...unlocks[o].map(t => y[t]));
      if (last !== null && oy < last + 90) oy = last + 90;
      last = oy;
      nodes.push({ id: `owned:${o}`, type: "ownedSkill", position: { x: -320, y: oy }, data: { label: o, proficiency: a.owned[o], status: "owned" } });
      for (const t of unlocks[o]) edges.push({ id: `unlocks:${o}->${t}`, source: `owned:${o}`, target: `step:${t}`, type: "smoothstep",
        label: "prerequisite", animated: true, data: { kind: "unlocks" } });
    }
    return { nodes, edges };
  };

  /* ── career pivot (score_pivot in app/graph/scoring.py) ── */
  NN.scorePivot = (userId, role, userSkills, jdSkills) => {
    const IMP = { core: 1.0, preferred: 0.6 };
    const all = [...role.core_skills.map(s => [s, "core"]), ...role.preferred_skills.map(s => [s, "preferred"])];
    let gap = 0, max = 0;
    const details = [], transferable = [], gaps = [];
    for (const [s, importance] of all) {
      const userP = userSkills[s.name] || 0, jdP = jdSkills[s.name] || 0, req = s.proficiency, tr = s.transferability;
      const eff = Math.max(userP, jdP * 0.9);
      let status, raw;
      if (eff >= req) { status = "met"; raw = 0; } else if (eff > 0) { status = "partial"; raw = (req - eff) * req; } else { status = "missing"; raw = req; }
      const wg = raw * (1 - tr * 0.4) * IMP[importance];
      gap += wg; max += req * IMP[importance];
      const d = { skill: s.name, category: s.category, importance, status, your_proficiency: eff, required: req,
                  transferability: tr, from_jd: jdP > 0 && jdP >= userP, gap_contribution: round3(wg) };
      details.push(d);
      if (status === "met" && tr >= 0.7) transferable.push(s.name); else if (status !== "met") gaps.push(d);
    }
    const score = max > 0 ? 1 - gap / max : 1;
    let overlap = null;
    if (Object.keys(jdSkills).length) {
      const names = new Set(all.map(([s]) => s.name));
      overlap = Math.round(Object.keys(jdSkills).filter(k => names.has(k)).length / Math.max(names.size, 1) * 100);
    }
    const [effort, label] = score >= 0.75 ? ["low", "You're already close — mostly upskilling"]
      : score >= 0.5 ? ["medium", "Achievable in 6–12 months of focused learning"]
      : ["high", "Significant reskilling required — 12–24 months"];
    gaps.sort((p, q) => (p.importance === "core" ? 0 : 1) - (q.importance === "core" ? 0 : 1) || q.gap_contribution - p.gap_contribution);
    return { user_id: userId, target_role: role.role_title, pivot_score: round3(score), effort, effort_label: label,
             transferable_skills: transferable, skill_gaps: gaps.slice(0, 6), skill_details: details,
             domains: role.domains, role_overlap_pct: overlap, jd_context_used: Object.keys(jdSkills).length > 0 };
  };

  /* ── deterministic stand-in for the LLM parser (demo only) ── */
  const AMBIGUOUS = new Set(["go", "r"]); // ordinary words; their aliases (golang, rstats) still match
  const LEXICON = [
    ...D.ontology.skills.map(s => [s.key, s.name]),
    ...Object.entries(D.ontology.aliases).map(([alias, key]) => [alias, SKILLS[key].name]),
  ].filter(([k]) => !AMBIGUOUS.has(k)).sort((a, b) => b[0].length - a[0].length);
  NN.lexicalSkills = text => {
    let t = " " + String(text).replace(/[,;:()!?"]/g, " ").replace(/\.(\s|$)/g, " ") + " ";
    t = " " + NN.canonicalKey(t) + " ";
    const found = [];
    for (const [key, name] of LEXICON) {
      const needle = ` ${key} `;
      if (t.includes(needle)) {
        if (!found.some(f => f.name === name)) found.push({ name, as: key });
        t = t.split(needle).join(" ~ "); // consume, so "vector db" isn't also read as something shorter
      }
    }
    return found;
  };

  window.NN = NN;
})();
